edits.after:
	for_each_btree_key_norestart(trans, bp_iter, BTREE_ID_backpointers,
			     *bp_pos, iter_flags, k, ret) {
	if (bpos_ge(k.k->p, bp_end_pos))
		break;

	if (k.k->type != KEY_TYPE_backpointer)
		continue;

	*bp_pos = k.k->p;
	*bp = *bkey_s_c_to_backpointer(k).v;
	goto out;
}

edits.before:
	for_each_btree_key_norestart(trans, bp_iter, BTREE_ID_backpointers,
			     *bp_pos, iter_flags, k, ret) {
	if (bpos_ge(k.k->p, bp_end_pos))
		break;

	*bp_pos = k.k->p;
	*bp = *bkey_s_c_to_backpointer(k).v;
	goto out;
}
